TEST_CASE("resume issues exactly one COMMAND per programmed register")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  hybrid::ResumeDriver driver(bus);
  driver.resume(rv64_state(0x80001000, 0));

  // x1..x31 + DPC at minimum (x0 skipped). We do not yet program FPR/CSR/V.
  CHECK(find_write(bus.ops, kCommand).size() >= 32u);
}

namespace {

auto cmd_regnos(const std::vector<DmiOp>& ops) -> std::vector<uint16_t>
{
  std::vector<uint16_t> ns;
  for (const auto& op : ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand)
      ns.push_back(static_cast<uint16_t>(op.value & 0xffffu));
  return ns;
}

auto contains_regno(const std::vector<uint16_t>& ns, uint16_t regno) -> bool
{
  for (auto n : ns) if (n == regno) return true;
  return false;
}

}  // namespace

TEST_CASE("resume does NOT program M-mode CSRs/PMP via DM Abstract Commands; "
          "those fields are pass-through-merged at drain time instead")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.mstatus = 0x1800ULL;
  for (int i = 0; i < HYBRID_PMP_CFG_NUM; ++i)  s.pmpcfg[i]  = 0xa0 + i;
  for (int i = 0; i < HYBRID_PMP_ADDR_NUM; ++i) s.pmpaddr[i] = 0xb0 + i;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  const auto ns = cmd_regnos(bus.ops);
  // mcycle(0xb00)/minstret(0xb02) are restored by resume (F-T2.4), and
  // mtvec(0x305)/mscratch(0x340) as tolerant M-mode CSRs (L23) -- none of
  // those belong in this "must not program" list. It covers mstatus(0x300,
  // restored only under FP/V; this state has neither) plus the S-mode CSRs
  // medeleg(0x302)/mideleg(0x303)/satp(0x180) that the M-only default engine
  // does not implement, and the whole PMP config block -- those stay
  // drain-time pass-through.
  for (uint16_t csr : {0x300, 0x302, 0x303, 0x180})
    CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(csr)));
  for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; ++i)
    CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(0x3a0 + i)));
}

namespace {

// COMMAND index of the first abstract write targeting regno, if any.
auto first_cmd_idx(const std::vector<DmiOp>& ops, uint16_t regno)
  -> std::optional<std::size_t>
{
  for (std::size_t i = 0; i < ops.size(); ++i) {
    const auto& op = ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xffffu) == regno)
      return i;
  }
  return std::nullopt;
}

}  // namespace

TEST_CASE("resume with HYBRID_FLAG_FP programs f0..f31 via Abstract Commands")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_FP;
  s.mstatus = 0x6000ULL;  // mstatus.FS = Dirty: FPRs are writable
  for (int i = 0; i < 32; ++i) s.fpr[i] = 0xf000000000000000ULL + i;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  const auto ns = cmd_regnos(bus.ops);
  for (uint16_t i = 0; i < 32; ++i)
    CHECK(contains_regno(ns, hybrid::regno_fpr(i)));
}

TEST_CASE("mstatus (FS enable) is written before the FPR abstract command")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_FP;
  s.mstatus = 0x2000ULL;
  s.fpr[0] = 0xabcd;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  const auto mstatus_idx = first_cmd_idx(bus.ops, hybrid::regno_csr(0x300));
  const auto fpr_idx     = first_cmd_idx(bus.ops, hybrid::regno_fpr(0));
  REQUIRE(mstatus_idx);
  REQUIRE(fpr_idx);
  CHECK(*mstatus_idx < *fpr_idx);
}

TEST_CASE("FPR write carries its state value via DATA0/DATA1 before the COMMAND")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  constexpr uint64_t f0 = 0xCAFEF00D'12345678ULL;
  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_FP;
  s.mstatus = 0x2000ULL;
  s.fpr[0] = f0;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  const auto fpr_cmd = first_cmd_idx(bus.ops, hybrid::regno_fpr(0));
  REQUIRE(fpr_cmd);
  REQUIRE(*fpr_cmd >= 2);
  const auto& d0 = bus.ops[*fpr_cmd - 2];
  const auto& d1 = bus.ops[*fpr_cmd - 1];
  CHECK(d0.reg == kData0);
  CHECK(d0.value == uint32_t(f0 & 0xffffffffu));
  CHECK(d1.reg == kData1);
  CHECK(d1.value == uint32_t((f0 >> 32) & 0xffffffffu));
}

TEST_CASE("B4: drained mstatus.FS = Off still writes mstatus with FS forced Initial")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_FP;
  s.mstatus = 0x0ULL;  // FS = Off in the drained state
  s.fpr[0] = 0x1;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  // mstatus (0x300) is still programmed, and DATA0 carries FS = Initial even
  // though the drained field was Off -- otherwise the FPR write would NACK.
  const auto mstatus_cmd = first_cmd_idx(bus.ops, hybrid::regno_csr(0x300));
  REQUIRE(mstatus_cmd);
  REQUIRE(*mstatus_cmd >= 2);
  const auto& d0 = bus.ops[*mstatus_cmd - 2];
  CHECK(d0.reg == kData0);
  CHECK((d0.value & 0x6000u) == 0x2000u);  // FS = Initial forced
}

TEST_CASE("resume without HYBRID_FLAG_FP: no FPR Abstract Commands issued")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  for (int i = 0; i < 32; ++i) s.fpr[i] = 0xf000000000000000ULL + i;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  const auto ns = cmd_regnos(bus.ops);
  for (uint16_t i = 0; i < 32; ++i)
    CHECK_FALSE(contains_regno(ns, hybrid::regno_fpr(i)));
}

TEST_CASE("L20: resume with HYBRID_FLAG_FP restores fcsr via abstract "
          "command, after the mstatus.FS enable")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_FP;
  s.mstatus = 0x6000ULL;
  s.fcsr = 0x21;  // frm=RTZ(1) << 5 | fflags=NX

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  const auto mstatus_idx = first_cmd_idx(bus.ops, hybrid::regno_csr(0x300));
  const auto fcsr_idx    = first_cmd_idx(bus.ops, hybrid::regno_csr(0x003));
  REQUIRE(mstatus_idx);
  REQUIRE(fcsr_idx);
  CHECK(*mstatus_idx < *fcsr_idx);

  // The fcsr value rides DATA0/DATA1 of that abstract write.
  REQUIRE(*fcsr_idx >= 2);
  const auto& d0 = bus.ops[*fcsr_idx - 2];
  const auto& d1 = bus.ops[*fcsr_idx - 1];
  CHECK(d0.reg == kData0);
  CHECK(d0.value == 0x21u);
  CHECK(d1.reg == kData1);
  CHECK(d1.value == 0u);
}

TEST_CASE("L20: resume without HYBRID_FLAG_FP issues no fcsr write")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.fcsr = 0x21;  // present in the file but FP not flagged live

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  CHECK_FALSE(contains_regno(cmd_regnos(bus.ops), hybrid::regno_csr(0x003)));
}

TEST_CASE("L23: resume restores mscratch (software scratch CSR) via an "
          "abstract command, carrying the drained value on DATA0/DATA1")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.mscratch = 0xCAFEBABEDEADBEEFULL;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  // Find the write-COMMAND targeting mscratch (0x340); its value rides the
  // DATA0/DATA1 written immediately before (same shape as the fcsr restore).
  std::optional<std::size_t> ms_cmd_idx;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xFFFFu) == hybrid::regno_csr(0x340)
        && ((op.value >> 16) & 1u)) {
      ms_cmd_idx = i;
      break;
    }
  }
  REQUIRE(ms_cmd_idx.has_value());
  REQUIRE(*ms_cmd_idx >= 2);
  const auto& d0 = bus.ops[*ms_cmd_idx - 2];
  const auto& d1 = bus.ops[*ms_cmd_idx - 1];
  CHECK(d0.kind == DmiOp::Kind::Write);
  CHECK(d0.reg == kData0);
  CHECK(d0.value == uint32_t(s.mscratch & 0xFFFFFFFFu));
  CHECK(d1.kind == DmiOp::Kind::Write);
  CHECK(d1.reg == kData1);
  CHECK(d1.value == uint32_t(s.mscratch >> 32));
}

TEST_CASE("resume restores mtvec + mcycle/minstret via abstract commands")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.mtvec    = 0x80000100ULL;
  s.mcycle   = 0x1111222233334444ULL;
  s.minstret = 0x5555666677778888ULL;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  // mtvec rides the tolerant CSR path; mcycle/minstret are restored (F-T2.4)
  // so the vsim phase keeps counting from QEMU1's drain.
  const auto ns = cmd_regnos(bus.ops);
  CHECK(contains_regno(ns, hybrid::regno_csr(0x305)));  // mtvec
  CHECK(contains_regno(ns, hybrid::regno_csr(0xB00)));  // mcycle
  CHECK(contains_regno(ns, hybrid::regno_csr(0xB02)));  // minstret
}

TEST_CASE("resume restores GPRs and FPRs via abstract writes only -- no "
          "Program Buffer execution")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_FP;
  s.mstatus = 0x6000ULL;  // FS = Dirty: FPRs writable
  for (uint16_t i = 1; i < 32; ++i) s.gpr[i] = 0xB0000000ULL + i;
  for (int i = 0; i < 32; ++i)      s.fpr[i] = 0xF0000000ULL + i;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  // Every GPR and FPR arrives via its own abstract register write...
  const auto ns = cmd_regnos(bus.ops);
  for (uint16_t i = 1; i < 32; ++i)
    CHECK(contains_regno(ns, hybrid::regno_gpr(i)));
  for (uint16_t i = 0; i < 32; ++i)
    CHECK(contains_regno(ns, hybrid::regno_fpr(i)));

  // ...and nothing rides the Program Buffer: with no abstract failure to
  // trigger the write_csr_abstract_or_pb fallback, no exec-progbuf COMMAND
  // is issued at all.
  for (const auto& op : bus.ops)
    CHECK_FALSE((op.kind == DmiOp::Kind::Write && op.reg == kCommand
                 && op.value == hybrid::kExecProgbufCmd));
}

TEST_CASE("B17: cleared cmderr surfaces via diagnostic side-channel")
{
  // clear_cmderr_if_set() swallows any sticky cmderr left by an earlier
  // per-register abstract failure so the resume can still proceed. Without a
  // side channel that swallow is invisible. Pin the contract: when a tolerant
  // CSR write fails, the driver records the last observed non-zero cmderr and
  // a non-zero clear count.
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);
  // Force the mtvec abstract write to fail. mtvec goes through
  // write_csr_tolerant which intentionally does NOT take the PB fallback; it
  // just clears cmderr at the end. So the failure is only visible via the
  // side channel.
  bus.fail_csr_write = 0x305;  // CSR mtvec

  hybrid::ResumeDriver driver(bus);
  driver.resume(rv64_state(0x80001000, 0));

  CHECK(driver.cmderr_clear_count() > 0u);
  CHECK(driver.last_observed_cmderr() != 0u);
}

TEST_CASE("B9: write_csr_abstract_or_pb busy-poll precedes cmderr inspection")
{
  // Every abstract register write (write_register_abstract) busy-polls
  // abstractcs before returning, so by the time any caller inspects cmderr
  // the busy bit is already clear. Pin that contract: between each kCommand
  // write and the next, the recorded ops must include at least one
  // kAbstractcs read (the busy poll). A refactor that drops the chained poll
  // regresses this test.
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  hybrid::ResumeDriver driver(bus);
  driver.resume(rv64_state(0x80001000, 0xdeadbeef));

  bool saw_cmd = false;
  std::size_t reads_since_cmd = 0;
  bool all_cmds_had_abstractcs_poll = true;
  for (const auto& op : bus.ops) {
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand) {
      if (saw_cmd && reads_since_cmd == 0)
        all_cmds_had_abstractcs_poll = false;
      saw_cmd = true;
      reads_since_cmd = 0;
    } else if (saw_cmd && op.kind == DmiOp::Kind::Read
               && op.reg == kAbstractcs) {
      ++reads_since_cmd;
    }
  }
  CHECK(all_cmds_had_abstractcs_poll);
  // The final kCommand write must also be followed by an abstractcs read.
  CHECK(reads_since_cmd > 0u);
}

